import{bV as a,aL as o,u as l,G as i}from"./chunks/framework.BfzMay2U.js";const b=JSON.parse('{"title":"分析 web 框架","description":"","frontmatter":{"title":"分析 web 框架","date":"2026-10-10T21:31:10.000Z"},"headers":[],"relativePath":"kratos/go-web/analyze.md","filePath":"kratos/go-web/analyze.md"}'),t={name:"kratos/go-web/analyze.md"};function r(d,e,s,h,c,n){return o(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="分析-web-框架" tabindex="-1">分析 web 框架 <a class="header-anchor" href="#分析-web-框架" aria-label="Permalink to &quot;分析 web 框架&quot;">​</a></h1><p>框架的设计原则：</p><ol><li>高内聚，低耦合，便于维护和拓展</li><li>封装底层实现，使用更为便捷</li><li>封装重复性代码，减少代码编写量</li><li>提供常用工具类</li></ol><p>框架的作用：</p><ol><li>协调资源，比如数据库，文件，缓存等</li><li>资源抽象，用于表示资源，程序通过一个抽象的概念与资源进行交互</li><li>通信，资源之间需要进行沟通交流</li><li>约定，大家遵照框架的约定，有助于简化框架的实现</li><li>环境，框架需要支持不同的应用环境</li><li>最主要的目的，让开发人员专注于编写业务逻辑，而不用关心别的事情</li></ol><h2 id="_1-路由" tabindex="-1">1. 路由 <a class="header-anchor" href="#_1-路由" aria-label="Permalink to &quot;1. 路由&quot;">​</a></h2><p>当我们需要访问服务提供的资源的时候，我们需要使用类似这样的请求方式：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/user/1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol><li>HTTP 是固定的，依据协议支持，用户可以自行访问 http 或者 https</li><li>localhost 代表本机，实际上 ip 是 127.0.0.1，需要注意域名实际上也是 ip 地址</li><li>8080 是端口，ip 和端口才能定位一个服务，域名的默认端口是 80，可以不写</li><li>GET 和 POST 是 http 的请求方式，类似的还有 PUT,DELETE,这些是我们程序需要支持的，同时是开发人员需要定义的</li></ol><blockquote><p>框架需要处理上方类似<code>/api/user/1</code>这样的路径请求，并根据请求的方式将其转发到具体的业务逻辑代码，也就是说在请求的<code>URL</code>和处理的函数之间，搭建一个桥梁，将它们准确的关联起来，这就是<strong>路由</strong></p></blockquote><h3 id="_1-1-请求参数" tabindex="-1">1.1 请求参数 <a class="header-anchor" href="#_1-1-请求参数" aria-label="Permalink to &quot;1.1 请求参数&quot;">​</a></h3><p>在进行路由匹配的时候，往往我们需要将请求携带的参数进行对应的解析，以便于后续的程序的需要。</p><ul><li>比如<code>?id=1</code>代表<code>get</code>传参</li><li><code>/get/user/:id</code>代表路径传参</li><li><code>post</code>传参中的<code>json</code>传参，以及文件传输等</li></ul><p>正常框架还应该支持<strong>参数校验</strong>等功能</p><h3 id="_1-2-表单" tabindex="-1">1.2 表单 <a class="header-anchor" href="#_1-2-表单" aria-label="Permalink to &quot;1.2 表单&quot;">​</a></h3><blockquote><p>请求参数的提交表单方式引用广泛，所以需要支持表单，通用需要支持表单参数校验</p></blockquote><h2 id="_2-处理器" tabindex="-1">2. 处理器 <a class="header-anchor" href="#_2-处理器" aria-label="Permalink to &quot;2. 处理器&quot;">​</a></h2><p>路由的功能就是将请求路由到具体的<code>Handler</code>处理器中，在处理器中，我们需要处理请求<code>request</code>，并且处理响应<code>response</code></p><p>应该提供完善的请求处理方式和响应方式</p><p>比如响应需要支持页面渲染，也需要支持<code>json</code>、<code>xml</code>和<code>html</code>等方式</p><h2 id="_3-中间件" tabindex="-1">3. 中间件 <a class="header-anchor" href="#_3-中间件" aria-label="Permalink to &quot;3. 中间件&quot;">​</a></h2><p>执行业务处理器的时候，往往需要再其前后进行一些功能的处理，但是并不希望入侵代码，这就是中间件的作用。</p><p>典型的有：</p><ol><li>日志</li><li>错误处理</li><li>认证权限</li><li>session</li><li>解析请求体等</li></ol><h2 id="_4-orm-支持" tabindex="-1">4. ORM 支持 <a class="header-anchor" href="#_4-orm-支持" aria-label="Permalink to &quot;4. ORM 支持&quot;">​</a></h2><p>应该支持流行的<code>ORM</code>，比如<code>gorm</code>，<code>xorm</code>或者自己实现的<code>orm</code></p><h2 id="_5-工具" tabindex="-1">5. 工具 <a class="header-anchor" href="#_5-工具" aria-label="Permalink to &quot;5. 工具&quot;">​</a></h2><p>比如常用的工具类，或者命令行工具，可以便捷生成代码。</p><h2 id="_6-配置项" tabindex="-1">6. 配置项 <a class="header-anchor" href="#_6-配置项" aria-label="Permalink to &quot;6. 配置项&quot;">​</a></h2><p>将用到的第三方的工具或者框架，做成可配置的，便于使用者进行替换。</p><h2 id="_7-插件" tabindex="-1">7. 插件 <a class="header-anchor" href="#_7-插件" aria-label="Permalink to &quot;7. 插件&quot;">​</a></h2><p>提供丰富的插件，可以便捷集成服务，比如<code>sentinel go</code>集成</p><h2 id="_8-http-协议支持" tabindex="-1">8. http 协议支持 <a class="header-anchor" href="#_8-http-协议支持" aria-label="Permalink to &quot;8. http 协议支持&quot;">​</a></h2><p>支持<code>http https http2</code>等</p><h2 id="_9-内置模版" tabindex="-1">9. 内置模版 <a class="header-anchor" href="#_9-内置模版" aria-label="Permalink to &quot;9. 内置模版&quot;">​</a></h2><p>使用内置模版引擎提供模版渲染机制</p>',36)])])}const u=a(t,[["render",r]]);export{b as __pageData,u as default};
